#include "stm32f411xe.h"
#include <stdint.h>
#include <stm32f4xx.h>

uint8_t estado_actual = 0;

int main(void)
{
    //Habilitad señal de reloj GPIOB
    RCC->AHB1ENR &= ~RCC_AHB1ENR_GPIOBEN; // Limpiar
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOBEN; // Activar

    //GPIOB

    // Verde
    GPIOB->MODER &= ~GPIO_MODER_MODER8;
    GPIOB->MODER |= GPIO_MODER_MODER8_0;
    GPIOB->OTYPER &= ~GPIO_OTYPER_OT8;
    GPIOB->OSPEEDR &= ~GPIO_OSPEEDR_OSPEED8;
    GPIOB->PUPDR &= ~GPIO_PUPDR_PUPD8;
    GPIOB->ODR &= ~GPIO_ODR_OD8;

    // Amarillo
    GPIOB->MODER &= ~GPIO_MODER_MODER9;
    GPIOB->MODER |= GPIO_MODER_MODER9_0;
    GPIOB->OTYPER &= ~GPIO_OTYPER_OT9;
    GPIOB->OSPEEDR &= ~GPIO_OSPEEDR_OSPEED9;
    GPIOB->PUPDR &= ~GPIO_PUPDR_PUPD9;
    GPIOB->ODR &= ~GPIO_ODR_OD9;

    // Rojo
    GPIOB->MODER &= ~GPIO_MODER_MODER6;
    GPIOB->MODER |= GPIO_MODER_MODER6_0;
    GPIOB->OTYPER &= ~GPIO_OTYPER_OT6;
    GPIOB->OSPEEDR &= ~GPIO_OSPEEDR_OSPEED6;
    GPIOB->PUPDR &= ~GPIO_PUPDR_PUPD6;
    GPIOB->ODR &= ~GPIO_ODR_OD6;

    //Configurar SysTick para que cuente 1000 ms
    SysTick->LOAD = 16000000 - 1; // Valor de recarga del contador
    SysTick->VAL = 0; // Reinicia el contador
    SysTick->CTRL &= ~SysTick_CTRL_TICKINT_Msk; // Deshabilitar interrupcion
    SysTick->CTRL |= (SysTick_CTRL_CLKSOURCE_Msk); // Selecionar reloj

    SysTick->CTRL &= ~SysTick_CTRL_ENABLE_Msk; // Limpiar el contador
    SysTick->CTRL |= SysTick_CTRL_ENABLE_Msk; // Habilitar el contador


    /* Loop forever */
	while (1) {
    
        // El bit COUNTFLAG se pone el 1 cuando el contador llega a 0,
        // y se limpia automaticamente al leer CTRL
        if (SysTick->CTRL & SysTick_CTRL_COUNTFLAG_Msk) {
        
            switch (estado_actual) {
            
                case 0:
                    GPIOB->ODR |= GPIO_ODR_OD8; // Encender LED verde
                    GPIOB->ODR &= ~GPIO_ODR_OD9; // Apagar LED amarillo
                    GPIOB->ODR &= ~GPIO_ODR_OD6; // Apagar LED rojo
                    estado_actual ++;
                    break;

                case 1:
                    GPIOB->ODR &= ~GPIO_ODR_OD8; // Apagar LED verde
                    GPIOB->ODR |= GPIO_ODR_OD9; // Encender LED amarillo
                    GPIOB->ODR &= ~GPIO_ODR_OD6; // Apagar LED rojo
                    estado_actual ++;
                    break;
                
                case 2:
                    GPIOB->ODR &= ~GPIO_ODR_OD8; // Apagar LED verde
                    GPIOB->ODR &= ~GPIO_ODR_OD9; // Apagar LED amarillo
                    GPIOB->ODR |= GPIO_ODR_OD6; // Encender LED rojo
                    estado_actual = 0;
                    break;

                default:
                    estado_actual = 0;
                    break;
            }
        }
    }
}
